<script setup>
import pmtGet from './components/pmtGet.vue'
import pmtCard from './components/pmtCard.vue'
import { ref, onMounted, computed } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const songList = ref({})
const showType0 = ref(false)
const selectedYear = ref('2026')

const yearConfig = {
  2024: {
    color: '#3E3146',
    text: '#F7ED01',
    file: '/files/pmt/maps2024.json'
  },
  2025: {
    color: '#323232',
    text: '#FF8E34',
    file: '/files/pmt/maps2025.json'
  },
  2026: {
    color: '#322A61',
    text: '#FFFFFF',
    file: '/files/pmt/maps2026.json'
  }
}

const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const poolText = computed(() => showType0.value ? '决赛' : '海选')

const filteredSongList = computed(() => {
  const result = {}
  for (const key in songList.value) {
    const item = songList.value[key]
    if (!showType0.value && item?.Type !== 1) continue
    result[key] = item
  }
  return result
})

const fetchSongData = async () => {
  try {
    const filePath = yearConfig[selectedYear.value].file
    const data = await pmtGet.methods.getPmt(filePath)
    songList.value = data
  } catch (error) {
    console.error('获取歌曲数据失败：', error)
    songList.value = {}
  }
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

onMounted(async () => {
  await fetchSongData()
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="song-container">
    <div class="control-wrapper">
      <div class="year-tabs">
        <button
          :class="['year-btn', { active: selectedYear === '2024' }]"
          @click="changeYear('2024')"
          :style="{ backgroundColor: selectedYear === '2024' ? yearColor : '#f5f5f5', color: selectedYear === '2024' ? yearTextColor : '#000' }"
        >
          2024
        </button>
        <button
          :class="['year-btn', { active: selectedYear === '2025' }]"
          @click="changeYear('2025')"
          :style="{ backgroundColor: selectedYear === '2025' ? yearColor : '#f5f5f5', color: selectedYear === '2025' ? yearTextColor : '#000' }"
        >
          2025
        </button>
        <button
          :class="['year-btn', { active: selectedYear === '2026' }]"
          @click="changeYear('2026')"
          :style="{ backgroundColor: selectedYear === '2026' ? yearColor : '#f5f5f5', color: selectedYear === '2026' ? yearTextColor : '#000' }"
        >
          2026
        </button>
      </div>

      <div class="view-switch" v-if="Number(selectedYear) < 2027">
        <button
          class="switch-btn"
          :class="{ active: !showType0 }"
          @click="showType0 = false"
          :style="{ 
            backgroundColor: !showType0 ? yearColor : 'transparent',
            color: !showType0 ? yearTextColor : '#ffffff'
          }"
        >
          预选赛
        </button>
        <button
          class="switch-btn"
          :class="{ active: showType0 }"
          @click="showType0 = true"
          :style="{ 
            backgroundColor: showType0 ? yearColor : 'transparent',
            color: showType0 ? yearTextColor : '#ffffff',
          }"
        >
          淘汰赛 / 决赛
        </button>
      </div>
    </div>

    <div v-for="(songItem, songKey) in filteredSongList" :key="songKey" class="song-section">
      <pmt-card 
        class="song-card" 
        :song-data="songItem" 
        :song-key="songKey" 
        :main-color="yearColor"
        :text-color="yearTextColor"
      />
    </div>
  </div>
</template>

<style scoped>
.song-container {
  max-width: 1500px;
  margin: 0 auto;
  padding: 20px;
}

.control-wrapper {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.year-tabs {
  display: flex;
  gap: 8px;
}

.year-btn {
  padding: 6px 16px;
  border: none;
  font-size: 18px;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
}

.view-switch {
  display: flex;
  border: 1px solid #ffffff;
  overflow: hidden;
}
.switch-btn {
  padding: 4px 14px;
  border: none;
  font-size: 16px;
  cursor: pointer;
  background: transparent;
}
.switch-btn.active {
  font-weight: bold;
}

.song-section {
  margin-bottom: 16px;
}

.song-card {
  width: 100%;
}
</style>