<script setup>
import lvmdfGet from './components/lvmdfGet.vue'
import lvmdfCard from './components/lvmdfCard.vue'
import { ref, onMounted, computed } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const songlvmdf = ref({})
const selectedVersion = ref('3.18.4')

const commonConfig = {
  color: '#212426',  
  text: '#ffffff'  
}

const versionConfig = {
  '2.5.0': { file: '/files/lvmdf/lvmdf2.5.0.json' },
  '3.2.0': { file: '/files/lvmdf/lvmdf3.2.0.json' },
  '3.5.0': { file: '/files/lvmdf/lvmdf3.5.0.json' },
  '3.9.0': { file: '/files/lvmdf/lvmdf3.9.0.json' },
  '3.11.0': { file: '/files/lvmdf/lvmdf3.11.0.json' },
  '3.15.1': { file: '/files/lvmdf/lvmdf3.15.1.json' },
  '3.18.3': { file: '/files/lvmdf/lvmdf3.18.3.json' },
  '3.18.4': { file: '/files/lvmdf/lvmdf3.18.4.json' },
}

const mainColor = computed(() => commonConfig.color)
const textColor = computed(() => commonConfig.text)

const fetchSongData = async () => {
  try {
    const filePath = versionConfig[selectedVersion.value].file
    const data = await lvmdfGet.methods.getLVMDF(filePath)
    songlvmdf.value = data
  } catch (error) {
    console.error('获取数据失败：', error)
    songlvmdf.value = {}
  }
}

const changeVersion = (version) => {
  selectedVersion.value = version
  fetchSongData()
}

onMounted(async () => {
  await fetchSongData()
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="song-container">
    <div class="version-tabs">
      <button
        v-for="version in ['2.5.0', '3.2.0', '3.5.0', '3.9.0', '3.11.0', '3.15.1', '3.18.3', '3.18.4']"
        :key="version"
        :class="['version-btn', { active: selectedVersion === version }]"
        @click="changeVersion(version)"
      >
        {{ version }}
      </button>
    </div>

    <div class="card-grid">
      <div 
        v-for="(songItem, songKey) in songlvmdf" 
        :key="songKey" 
        class="grid-item"
      >
        <lvmdf-card 
          :song-data="songItem" 
          :song-key="songKey" 
          :main-color="mainColor"
          :text-color="textColor" 
        />
      </div>
    </div>
  </div>
</template>

<style scoped>
.song-container {
  max-width: 1500px;
  margin: 0 auto;
  padding: 20px;
}

.version-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.version-btn {
  padding: 6px 16px;
  border: none;
  font-size: 18px;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
  background: #ffffff;
  color: #000000;
}

.version-btn.active {
  background: #212426;
  color: #ffffff;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}

.version-btn:hover:not(.active) {
  background: #e9e9e9;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  width: 100%;
  box-sizing: border-box;
  min-width: 0;
}

.grid-item {
  width: 100%;
}
</style>